// C tests of the smoketest's pure helpers (#1589), built by `make selftest` as its own binary and run
// by run.sh under the same sanitizers. It never feeds the coverage run, which comes from the
// mods/coverage/ tests alone, and it replaces none of them: a behaviour enters the smoketest only
// through a committed grug test.
//
// Every expected number below is a known-answer vector printed by java.util.Random on the local JDK:
//   $ java -version
//   openjdk version "21.0.13.1" 2026-11-17
//   OpenJDK Runtime Environment (build 21.0.13.1+2)
// Each row is one `new Random(seed)` followed by its calls in the order of the columns, so a draw
// depends on every draw before it. Doubles are printed with Double.toHexString, which is exact.
#define main smoketest_main
#include "smoketest.c"
#undef main

static int checks, failures;
#define CHECK(cond, ...) do { checks++; if (!(cond)) { failures++; printf("SELFTEST FAIL line %d: ", __LINE__); printf(__VA_ARGS__); printf("\n"); } } while (0)

struct vec {
    long long seed;
    int next_int[4];              // nextInt(), four calls
    int bound10[4];               // nextInt(10), a bound that is not a power of two
    int bound16[4];               // nextInt(16), a power of two
    int bound1000[4];             // nextInt(1000)
    int bound_max[4];             // nextInt(2147483647)
    double next_float[3];         // nextFloat()
    double next_double[3];        // nextDouble()
    double gaussian[5];           // nextGaussian(), an odd count so the cache is left full
};

// seed 42, 0 and 123456789012345, generated by the Gen program run with `java Gen.java`
static const struct vec vecs[] = {
    {42LL, {-1170105035, 234785527, -1360544799, 205897768}, {0, 5, 5, 8}, {10, 1, 14, 7}, {276, 292, 476, 32}, {995688456, 1636576170, 1681268743, 2143572209}, {0x1.d6b22p-1, 0x1.3735ep-3, 0x1.bef77cp-2}, {0x1.c25ae2bff9d9cp-2, 0x1.dc7bb0b17b05ep-1, 0x1.98b90616b4568p-1}, {-0x1.db0091658e302p-1, -0x1.b7916f10a0315p-2, -0x1.5347487c1a372p0, -0x1.6ef432ef24896p-1, -0x1.7e1d6c3dcd4f5p-1}},
    {0LL, {-1155484576, -723955400, 1033096058, -1690734402}, {5, 3, 1, 1}, {9, 12, 5, 4}, {473, 262, 95, 844}, {1888030084, 49567875, 2021317241, 377907320}, {0x1.198d88p-2, 0x1.407248p-2, 0x1.07fb38p-3}, {0x1.78cea32587af8p-2, 0x1.690caa02f9778p-1, 0x1.6b828bf723p-10}, {-0x1.9f9198b440a79p-3, 0x1.aa6d154e39dc4p-6, -0x1.f868685defc2fp-1, -0x1.b50146fff6cbcp-1, 0x1.97e41e94f68acp-2}},
    {123456789012345LL, {-1421006947, -2071311287, -583755257, -1678701992}, {5, 8, 0, 9}, {13, 6, 13, 9}, {156, 768, 488, 241}, {1448108067, 496414028, 1442016227, 479138592}, {0x1.8dfd8p-4, 0x1.bf1108p-1, 0x1.326962p-1}, {0x1.d9b7564ed3b8ep-2, 0x1.6150963abdf94p-3, 0x1.b2f13fcb67b89p-1}, {-0x1.c911b23047d2cp-1, -0x1.4ed9c86b08351p-3, -0x1.990077d6868c3p-2, -0x1.5f1c5216c0266p-1, -0x1.cb48e6037a7f4p0}},
};

static void test_random(void) {
    for (size_t v = 0; v < sizeof vecs / sizeof vecs[0]; v++) {
        const struct vec* e = &vecs[v];
        rnd_set_seed(e->seed);
        for (int i = 0; i < 4; i++) CHECK(rnd_next(32) == e->next_int[i], "seed %lld nextInt() #%d", e->seed, i);
        for (int i = 0; i < 4; i++) CHECK(rnd_next_int(10) == e->bound10[i], "seed %lld nextInt(10) #%d", e->seed, i);
        for (int i = 0; i < 4; i++) CHECK(rnd_next_int(16) == e->bound16[i], "seed %lld nextInt(16) #%d", e->seed, i);
        for (int i = 0; i < 4; i++) CHECK(rnd_next_int(1000) == e->bound1000[i], "seed %lld nextInt(1000) #%d", e->seed, i);
        for (int i = 0; i < 4; i++) CHECK(rnd_next_int(2147483647u) == e->bound_max[i], "seed %lld nextInt(MAX) #%d", e->seed, i);
        for (int i = 0; i < 3; i++) CHECK(rnd_float() == e->next_float[i], "seed %lld nextFloat() #%d", e->seed, i);
        for (int i = 0; i < 3; i++) CHECK(rnd_double() == e->next_double[i], "seed %lld nextDouble() #%d", e->seed, i);
        for (int i = 0; i < 5; i++) CHECK(rnd_gaussian() == e->gaussian[i], "seed %lld nextGaussian() #%d", e->seed, i);
    }
    // A bound of 1431655765 makes the first draw of seed 0 hit Java's rejection loop (u - r + m
    // overflows), so the result comes from a later draw. new Random(0).nextInt(1431655765) is 516548029
    // on the local JDK above.
    rnd_set_seed(0);
    CHECK(rnd_next_int(1431655765u) == 516548029, "rejection loop");
    // nextInt(1) is always 0 and consumes one draw: the next nextInt() follows it.
    rnd_set_seed(42);
    CHECK(rnd_next_int(1) == 0, "nextInt(1)");
    CHECK(rnd_next(32) == 234785527, "draw after nextInt(1)");
    // rnd_reset is new Random(42), so the first nextInt() is the seed 42 vector's first.
    rnd_reset();
    CHECK(rnd_next(32) == -1170105035, "rnd_reset is seed 42");
    // new Random(42).nextGaussian() three times (java.util.Random, same JDK): the second call returns
    // the cached value of the first pair. Setting a seed discards that cache, as Java's setSeed does.
    rnd_set_seed(42);
    CHECK(rnd_gaussian() == 0x1.2453e82115d86p0, "first gaussian of seed 42");
    CHECK(rnd_gaussian() == 0x1.d6bca38120847p-1, "cached second gaussian");
    CHECK(rnd_gaussian() == -0x1.e654eb7a040c2p-1, "third gaussian starts a new pair");
    rnd_set_seed(42);
    (void)rnd_gaussian();
    rnd_set_seed(42);
    CHECK(rnd_gaussian() == 0x1.2453e82115d86p0, "setSeed clears the cached gaussian");
}

// strict_log is fdlibm's log. The seed 42 gaussians above are its known-answer test against Java's
// StrictMath.log (glibc's log is one bit off there); these rows reach its other paths, and their
// expected values are mathematical constants, not JDK output.
static void test_strict_log(void) {
    CHECK(strict_log(1.0) == 0.0, "log 1");
    CHECK(strict_log(0.0) == -INFINITY, "log 0");
    CHECK(isnan(strict_log(-1.0)), "log negative");
    CHECK(isinf(strict_log(INFINITY)) && strict_log(INFINITY) > 0, "log infinity");
    CHECK(isnan(strict_log(NAN)), "log nan");
    CHECK(fabs(strict_log(4.9e-324) - (-744.4400719213812)) < 1e-9, "log of the smallest subnormal");
    CHECK(fabs(strict_log(1.0 + 0x1p-30) - (0x1p-30 - 0x1p-61)) < 1e-24, "log near 1");
    CHECK(fabs(strict_log(2.0) - 0.6931471805599453) < 1e-15, "log 2");
    CHECK(fabs(strict_log(1e300) - 690.7755278982137) < 1e-12, "log 1e300");
}

static void test_index(void) {
    CHECK(check_index(0, 1, true) == IDX_OK, "first of one");
    CHECK(check_index(2, 3, true) == IDX_OK, "last of three");
    CHECK(check_index(3, 3, true) == IDX_NO_RECORD, "one past the end");
    CHECK(check_index(0, 0, true) == IDX_NO_RECORD, "empty list");
    CHECK(check_index(0, 0, false) == IDX_NO_RECORD, "list never created");
    CHECK(check_index(1e9, 3, true) == IDX_NO_RECORD, "far past the end");
    CHECK(check_index(2147483647.0, 3, true) == IDX_NO_RECORD, "largest int index");
    CHECK(check_index(2147483648.0, 3, true) == IDX_NOT_WHOLE, "past the int range");
    CHECK(check_index(-1, 3, true) == IDX_NOT_WHOLE, "negative");
    CHECK(check_index(-0.5, 3, true) == IDX_NOT_WHOLE, "negative fraction");
    CHECK(check_index(1.5, 3, true) == IDX_NOT_WHOLE, "fraction");
    CHECK(check_index(NAN, 3, true) == IDX_NOT_WHOLE, "nan");
    CHECK(check_index(INFINITY, 3, true) == IDX_NOT_WHOLE, "infinity");
    CHECK(check_index(-INFINITY, 3, true) == IDX_NOT_WHOLE, "negative infinity");
}

int main(void) {
    test_random();
    test_strict_log();
    test_index();
    printf("selftest: %d checks, %d failed\n", checks, failures);
    return failures ? 1 : 0;
}
